import React, {
  ForwardedRef,
  forwardRef,
  useImperativeHandle,
  useMemo,
  useRef,
} from 'react';
import {ScrollView, Text, View} from 'react-native';
import {Theme} from '../../types/interfaces';
import {RulesSection} from '../../lib/rules/types';
import styles from '../../styles/RulesScreenStyles';

interface RulesDocumentViewProps {
  sections: RulesSection[];
  query: string;
  theme: Theme;
  onAnchorNavigation?: (anchor: string) => void;
}

export interface RulesDocumentViewHandle {
  scrollToAnchor: (anchor: string) => void;
}

interface HighlightPart {
  text: string;
  highlighted: boolean;
}

function splitHighlight(text: string, query: string): HighlightPart[] {
  const normalized = query.trim().toLowerCase();
  if (!normalized) {
    return [{text, highlighted: false}];
  }

  const sourceLower = text.toLowerCase();
  const parts: HighlightPart[] = [];
  let cursor = 0;

  while (cursor < text.length) {
    const hit = sourceLower.indexOf(normalized, cursor);
    if (hit === -1) {
      parts.push({text: text.slice(cursor), highlighted: false});
      break;
    }

    if (hit > cursor) {
      parts.push({text: text.slice(cursor, hit), highlighted: false});
    }

    parts.push({
      text: text.slice(hit, hit + normalized.length),
      highlighted: true,
    });
    cursor = hit + normalized.length;
  }

  return parts.filter(part => part.text.length > 0);
}

const RulesDocumentView = forwardRef(
  (
    {sections, query, theme, onAnchorNavigation}: RulesDocumentViewProps,
    ref: ForwardedRef<RulesDocumentViewHandle>,
  ) => {
    const scrollRef = useRef<ScrollView>(null);
    const anchorPositionsRef = useRef<Record<string, number>>({});

    const normalizedQuery = useMemo(() => query.trim(), [query]);

    const scrollToAnchor = (anchor: string) => {
      const y = anchorPositionsRef.current[anchor];
      if (typeof y !== 'number') {
        return;
      }
      scrollRef.current?.scrollTo({
        y: Math.max(0, y - 8),
        animated: true,
      });
    };

    useImperativeHandle(ref, () => ({
      scrollToAnchor,
    }));

    return (
      <ScrollView
        testID="rules-document-scroll"
        ref={scrollRef}
        style={styles.contentContainer}
        contentContainerStyle={{
          ...styles.docContent,
          backgroundColor: theme.backgroundColor,
        }}>
        {sections.map(section => (
          <View
            key={section.anchor}
            testID={`rules-section-${section.anchor}`}
            onLayout={event => {
              anchorPositionsRef.current[section.anchor] =
                event.nativeEvent.layout.y;
            }}>
            <Text style={{...styles.headingText, color: theme.foregroundColor}}>
              {section.title}
            </Text>
            {section.blocks
              .filter(block => block.type !== 'heading')
              .map((block, blockIndex) => (
                <Text
                  key={`${section.anchor}-${blockIndex}`}
                  style={{...styles.paragraphText, color: theme.foregroundColor}}>
                  {block.textRuns.map((run, runIndex) => {
                    const hrefAnchor = run.href?.startsWith('#')
                      ? run.href.slice(1)
                      : null;
                    const textParts = splitHighlight(run.text, normalizedQuery);
                    return (
                      <Text
                        key={`${section.anchor}-${blockIndex}-${runIndex}`}
                        testID={
                          hrefAnchor
                            ? `rules-inline-link-${section.anchor}-${blockIndex}-${runIndex}`
                            : undefined
                        }
                        onPress={
                          hrefAnchor
                            ? () => {
                                scrollToAnchor(hrefAnchor);
                                onAnchorNavigation?.(hrefAnchor);
                              }
                            : undefined
                        }
                        style={
                          hrefAnchor
                            ? {
                                color: theme.foregroundColor,
                                ...styles.linkText,
                              }
                            : {
                                color: theme.foregroundColor,
                              }
                        }>
                        {textParts.map((part, partIndex) => (
                          <Text
                            key={`${section.anchor}-${blockIndex}-${runIndex}-${partIndex}`}
                            style={
                              part.highlighted
                                ? {
                                    color: theme.foregroundColor,
                                    ...styles.highlightText,
                                  }
                                : {color: theme.foregroundColor}
                            }>
                            {part.text}
                          </Text>
                        ))}
                      </Text>
                    );
                  })}
                </Text>
              ))}
          </View>
        ))}
      </ScrollView>
    );
  },
);

export default RulesDocumentView;
